package com.ryno.classrecorder.ui.components

import androidx.compose.ui.graphics.Color
import androidx.compose.ui.graphics.PathFillType
import androidx.compose.ui.graphics.SolidColor
import androidx.compose.ui.graphics.vector.ImageVector
import androidx.compose.ui.graphics.vector.addPathNodes
import androidx.compose.ui.unit.dp

/**
 * Zero-dependency Material Icons Rounded vector set (24dp) used across Class Recorder.
 * Eliminates ~58.6 MB of `material-icons-extended` DEX classes while keeping exact glyphs.
 */
object DshIcons {
    private val cache = HashMap<String, ImageVector>(40)
    private val blackFill = SolidColor(Color.Black)

    private fun icon(
        name: String,
        vararg paths: Pair<String, PathFillType>,
        autoMirror: Boolean = false
    ): ImageVector = synchronized(cache) {
        cache.getOrPut(name) {
            ImageVector.Builder(
                name = name,
                defaultWidth = 24.dp,
                defaultHeight = 24.dp,
                viewportWidth = 24f,
                viewportHeight = 24f,
                autoMirror = autoMirror
            ).apply {
                for ((svg, fillType) in paths) {
                    addPath(
                        pathData = addPathNodes(svg),
                        pathFillType = fillType,
                        fill = blackFill
                    )
                }
            }.build()
        }
    }

    private fun p(svg: String, evenOdd: Boolean = false): Pair<String, PathFillType> =
        svg to if (evenOdd) PathFillType.EvenOdd else PathFillType.NonZero

